WFJ.Data.add("gossip", {
  ["0001ce030c010973"] = { "Sergra cade in trance per un istante, poi guarda il cielo.", "." },
  ["000a2108cac39d63"] = { "Credo di capire, ora, come i Creatori abbiano concepito i Terrigeni. Quali sono le anomalie dei Terrigeni di cui parlavi prima?", "." },
  ["000a56d9887f267a"] = { "Riposo, {class}. Se sei solo di passaggio, ti consiglio di restare sulle strade e di viaggiare solo di giorno. Se invece hai affari qui a ⟦Darkshire=Borgoscuro⟧, valuta di mettere le tue capacità al servizio dei Guardiani della Notte. La nostra abilità è indiscutibile, ma siamo in pochi.", "." },
  ["001010be50d380ba"] = { "Salute, {race}.", "." },
  ["0013564921d90536"] = { "Locanda", "." },
  ["0014686cc1b2958f"] = { "Certo che me la ricordo quella notte. Due dita più a sinistra e adesso berresti con quell'elfo, Morris. Ed era pure la mia camicia migliore.", "." },
  ["0014764012a4629e"] = { "Tu?\n\n<Lorax ride.>\n\nNe dubito.\n\nMe ne sto tra queste rovine e sogno. Sogno il giorno in cui acciufferò quel miserabile ladro, Goraluk Anvilcrack.\n\nAvevamo un patto, io e lui. Un patto che lui ha infranto. Tradito.", "." },
  ["0014e53e39a9dc47"] = { "Ah sì?", "." },
  ["0014e6a939aa3bcc"] = { "Va bene!", "." },
  ["00187af7a5b49a4c"] = { "Ah, The Gilded Rose... con i suoi morbidi letti di piuma e i bagni caldi... solo a pensare a quella locanda mi viene voglia di... ::sbadiglio:: Che fortuna, se ci stai andando... la trovi sul lato ovest del ⟦Trade District=Quartiere del Commercio⟧. ...bei cuscini morbidi, coperte calde. ::sbadiglio::", "." },
  ["001c35bcc77747e8"] = { "Salve, clan Trias! Una mozzarella affumicata, per favore!", "." },
  ["002ba13882824d71"] = { "Se vai nella ⟦Alterac Valley=Valle d'Alterac⟧, parla con Kartra Bloodsnarl. La trovi nella Hall of the Brave, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["002beb9cc67ef907"] = { "È nella Città Vecchia che devi andare se cerchi dei ladri. Si trova nell'angolo nord-est di ⟦Stormwind=Roccavento⟧.", "." },
  ["0031b57f82491d22"] = { "Inchinatevi! Inginocchiatevi davanti al Brandicenere! Si avvicina una nuova alba, fratelli e sorelle! Il nostro messaggio giungerà alla feccia di questo mondo per mezzo del prescelto!", "." },
  ["00323f04e3847137"] = { "Splendido.\n\nIl totem che creerò per te è più di un simbolo: ha anche altri poteri. Uno degli usi del totem è come focus per gli incantesimi. Quegli incantesimi sono legati alla terra e, man mano che acquisirai sempre più saggezza, ti saranno resi accessibili altri poteri della terra. Gli istruttori che si trovano in tutto Kalimdor sapranno quando sarai pront<o/a> per conoscenze più grandi e te lo faranno sapere quando andrai da loro.\n\nMa per ora prendi questo totem della terra...", "." },
  ["0041efb63537c3c2"] = { "Ecco, Relara. Bevi questo...", "." },
  ["0046e0466525e0a0"] = { "La Frostwolf Relief Hut si trova nella ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧, a sud delle Torri dei Lupi Bianchi.\n\nAl momento è sotto il controllo dell'⟦Alliance=Alleanza⟧.", "." },
  ["004dcb42d7fc65ff"] = { "Ci sono diversi campi di battaglia tra cui scegliere. Da quale maestro delle battaglie vuoi che ti mandi?", "." },
  ["0053e8152b45869a"] = { "Shirvallah, riempimi della tua FURIA!", "." },
  ["0054c30ca498dbba"] = { "In quanto {class}, fai parte della ristretta cerchia di chi sa evocare un portale che ti riporta proprio in questo luogo. Posso insegnartelo, se sei <pronto/pronta>.", "." },
  ["0055b5630679875c"] = { "È in aria e....è dentro!", "." },
  ["0056137af31d7ff9"] = { "%s porta il boccale all'occhio e si acciglia.", "." },
  ["005847de91a591ea"] = { "Mi hanno visto! Arriva {name}! Aiuto!", "." },
  ["006921c124c689f8"] = { "Salve, {name}. Benvenut<o/a> al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "." },
  ["006ac1f4a6ecd4ee"] = { "⟦Icebane Breastplate=Pettorale Corazzato della Rovina dei Ghiacci⟧.", "." },
  ["006bbcd057e05bf0"] = { "C'è Flagello fuori da ⟦Trade Quarter=Quartiere del Commercio⟧!", "." },
  ["006cb3eb84e6a296"] = { "Nessuno torca un capello a Reginald Windsor! Deve passare indisturbato!", "." },
  ["006d778faaf3e864"] = { "Cerco altro addestramento druidico per comprendere più da vicino la volontà della Madre Terra.", "." },
  ["0078ada2216c8839"] = { "Pare che la ⟦Syndicate=Lega dei Tagliagole⟧ stia ficcando il naso in una grotta sull'altopiano orientale. Scopri cosa stanno tramando, soldato! Occhio ai movimenti dei Lupi Bianchi!", "." },
  ["0078f083d5737c1d"] = { "Sì, devo andare avanti.", "." },
