  ["008b2e47d80a4539"] = { "%s colpisce solo il fianco della cassa!", "." },
  ["0092a889032e279d"] = { "Basta! Il gioco è finito!", "." },
  ["009711b7ba0b0ebb"] = { "<Braceardente si accorge della tua presenza.>", "." },
  ["009f08eabc8cd79e"] = { "Parlami del ⟦Beasts Deck=Mazzo delle Bestie⟧.", "." },
  ["00a7c27318553d17"] = { "Che ne pensi dello Snow Leopard, {name}?", "." },
  ["00ac689968b504ae"] = { "Sì, me l'aspettavo che saresti <tornato/tornata>. Prima ho mandato fuori Korra e ha trovato la Dartol's Rod, abbandonata nella foresta.\n\nAbbiamo faticato tanto per recuperarla, {name}. Ti prego, in futuro bada a non trattarla con tanta leggerezza.", "." },
  ["00b71ae1327411b4"] = { "Sono tempi pericolosi, <avventuriero/avventuriera>. Cammina con prudenza.", "." },
  ["00b7a8e6815c47cf"] = { "Prima che il tuo apprendimento abbia inizio, devo chiederti un favore...", "." },
  ["00be6edc84f898ef"] = { "Ti prego, insegnami.", "." },
  ["00ca38b984b22972"] = { "Sei qui per l'addestramento, per poi trasmetterlo ai tuoi famigli?", "." },
  ["00ce5f4ca62a5ef6"] = { "Ti prego, continua, eroe...", "." },
  ["00d0bb2cb05ef87a"] = { "Marketing - Saluto per il riscatto iCoke (S.H.E.)", "." },
  ["00d763c30917b3b0"] = { "Per millenni questo essere è rimasto assopito sotto il mondo, in attesa del suo momento. Dalla sua prigione ha atteso l'istante esatto in cui colpire chi voleva fargli del male.", "." },
  ["00d767a24a2a80d3"] = { "Dunque Hakkar è tornato?", "." },
  ["00d9e19801c0c351"] = { "Denni'ka può insegnarti a stare al caldo. Cercala a Survival of the Fittest, una capanna sulla riva del lago accanto alla Spirit Lodge. Sali e dirigiti a ovest, sopra la ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["00db43cef8c98f74"] = { "Dov'è l'anziano Proudhorn?", "." },
  ["00dbd44927b40790"] = { "Grazie per ciò che hai fatto, {name}.\n\nCustodisci lo scettro; possa aiutarti nella tua lotta contro i mali che hanno invaso questo luogo...", "." },
  ["00e85c169695a867"] = { "Scappa finché puoi!", "." },
